using System; using Inu.Kernel.TimerDispatch; namespace Inu.Samples.Service; public static unsafe class Sample { private static UInt64 _runs; public static Boolean Start(out UInt32 handle)=>KernelTimerDispatch.Register(1000000000UL,&Tick,0UL,out handle); public static Boolean Stop(UInt32 h)=>KernelTimerDispatch.Unregister(h); private static Boolean Tick(UInt64 c){_runs++;return true;} public static UInt64 Runs()=>_runs; }
